#!/usr/bin/env node
'use strict';
const fs=require('fs');
const path=require('path');
const crypto=require('crypto');
const root=path.resolve(__dirname,'..'),read=relative=>fs.readFileSync(path.join(root,relative),'utf8'),write=(relative,value)=>fs.writeFileSync(path.join(root,relative),value);
const order=['utils.js','feature-flags.js','rail-data-repository.js','asset-renderer.js','storage.js','typing.js','typing-model.js','statistics-engine.js','line-badge.js','station-sign-templates.js','transport-stop-templates.js','route-integrity.js','service-route-resolver.js','route-renderer.js','game.js','free-drive.js','statistics.js','network-map.js','data-loader.js','route-editor.js','auth.js','app.js'];
const source=order.map(file=>read(`js/${file}`).replace(/\bimport(?=\s|\{)[^;]+;/g,'').replace(/\bexport\s+/g,'').replace(/new URL\('\.\.\/data\/([^']+)',import\.meta\.url\)/g,"new URL('./data/$1',document.baseURI)")).join('\n\n');
const bundle=`/* AUTO-GENERATED by tools/build-static.js. DO NOT EDIT. */\n(()=>{'use strict';(async()=>{\n${source}\n})().catch(error=>{console.error('Tokyo Rail Typing failed to start:',error);const toast=document.querySelector('#toast');if(toast){toast.textContent='게임을 시작하지 못했습니다. 새로고침해 주세요.';toast.classList.add('show')}})})();\n`;
write('js/app.bundle.js',bundle);
const hash=crypto.createHash('sha256').update(bundle).digest('hex').slice(0,12),html=read('index.html').replace(/(\.\/js\/app\.bundle\.js)(?:\?v=[^"']*)?/g,`$1?v=${hash}`);write('index.html',html);
console.log(JSON.stringify({bundle:'js/app.bundle.js',hash},null,2));
